"""Import STM32 SD-card inference logs and compute accuracy."""

from __future__ import annotations

import csv
import shutil
from collections import Counter, defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Tuple

from .metadata import LEGACY_RESULTS_NAMES, RESULTS_NAME, RunMetadata


# Matches capture_sd_log.cpp header on the STM32 firmware.
SD_CSV_FIELDS = [
    "id",
    "gate_pred",
    "pct_leaf",
    "pct_others",
    "pct_pest",
    "disease_pred",
    "gate_ms",
    "infer_ms",
    "bmp",
]

# Generated by AATBS itself — not treated as the SD inference CSV.
_SKIP_CSV_NAMES = {RESULTS_NAME.lower(), *(n.lower() for n in LEGACY_RESULTS_NAMES)}



@dataclass
class InferenceRow:
    id: int
    gate_pred: str
    pct_leaf: int
    pct_others: int
    pct_pest: int
    disease_pred: str
    gate_ms: int
    infer_ms: int
    bmp: str


@dataclass
class PairResult:
    index: int
    ground_truth: str
    filename: str
    disease_pred: str
    gate_pred: str
    correct: bool
    skipped: bool
    infer_ms: int
    gate_ms: int


@dataclass
class AnalysisReport:
    paired: List[PairResult] = field(default_factory=list)
    unmatched_meta: int = 0
    unmatched_preds: int = 0
    overall_accuracy: float = 0.0
    evaluated: int = 0
    correct: int = 0
    skipped: int = 0
    per_class: Dict[str, Dict[str, float]] = field(default_factory=dict)
    confusion: Dict[str, Counter] = field(default_factory=dict)
    gate_counts: Counter = field(default_factory=Counter)
    mean_infer_ms: float = 0.0
    mean_gate_ms: float = 0.0

    def summary_lines(self) -> List[str]:
        lines = [
            f"Paired samples: {len(self.paired)}",
            f"Evaluated (non-SKIP): {self.evaluated}",
            f"Correct: {self.correct}",
            f"Skipped by gate/device: {self.skipped}",
            f"Overall disease accuracy: {self.overall_accuracy * 100:.2f}%",
            f"Mean gate time: {self.mean_gate_ms:.1f} ms",
            f"Mean infer time: {self.mean_infer_ms:.1f} ms",
            f"Unmatched metadata rows: {self.unmatched_meta}",
            f"Unmatched prediction rows: {self.unmatched_preds}",
            "",
            "Per-class accuracy:",
        ]
        for cls, stats in sorted(self.per_class.items()):
            lines.append(
                f"  {cls}: {stats['accuracy'] * 100:.2f}% "
                f"({int(stats['correct'])}/{int(stats['total'])})"
            )
        lines.append("")
        lines.append("Gate predictions:")
        for name, count in self.gate_counts.most_common():
            lines.append(f"  {name}: {count}")
        return lines


def list_csv_files(folder: Path, *, exclude_results: bool = False) -> List[Path]:
    """Return .csv files directly inside folder (non-recursive)."""
    folder = Path(folder)
    if not folder.is_dir():
        return []
    files = sorted(p for p in folder.iterdir() if p.is_file() and p.suffix.lower() == ".csv")
    if exclude_results:
        files = [p for p in files if p.name.lower() not in _SKIP_CSV_NAMES]
    return files


def pick_single_csv(folder: Path, *, exclude_results: bool = False, label: str = "folder") -> Path:
    """
    Use the only .csv in a folder.

    Raises FileNotFoundError if none, ValueError if two or more.
    """
    files = list_csv_files(folder, exclude_results=exclude_results)
    if len(files) == 0:
        raise FileNotFoundError(f"No .csv file found in {label}: {folder}")
    if len(files) >= 2:
        names = ", ".join(p.name for p in files)
        raise ValueError(
            f"Found {len(files)} .csv files in {label} (expected exactly one): {names}"
        )
    return files[0]


def find_sd_csv(sd_path: Path) -> Path:
    """
    Resolve the SD inference CSV.

    - If a .csv file is selected, use it.
    - If a folder is selected, use the single .csv inside it
      (analysis_results.csv / results.csv are ignored).
    - Error if the folder contains two or more inference .csv files.
    """
    sd_path = Path(sd_path).expanduser().resolve()
    if sd_path.is_file():
        if sd_path.suffix.lower() != ".csv":
            raise ValueError(f"Selected file is not a .csv: {sd_path.name}")
        if sd_path.name.lower() in _SKIP_CSV_NAMES:
            raise ValueError(
                f"{sd_path.name} is an AATBS analysis table, not an SD inference log."
            )
        return sd_path
    if not sd_path.is_dir():
        raise FileNotFoundError(f"SD path not found: {sd_path}")
    return pick_single_csv(sd_path, exclude_results=True, label="SD card folder")


def find_run_csv(run_dir: Path) -> Path:
    """Find the archived SD inference CSV inside a run folder (any name)."""
    return pick_single_csv(Path(run_dir), exclude_results=True, label="run folder")


def results_csv_path(run_dir: Path) -> Path | None:
    from .metadata import find_results_csv

    return find_results_csv(run_dir)


def load_results_csv(path: Path) -> List[PairResult]:
    """Load a previously written results.csv into PairResult rows."""
    path = Path(path)
    pairs: List[PairResult] = []
    with path.open(newline="", encoding="utf-8-sig") as fh:
        filtered = (
            line for line in fh if line.strip() and not line.lstrip().startswith("#")
        )
        reader = csv.DictReader(filtered)
        if not reader.fieldnames:
            raise ValueError(f"Empty results CSV: {path}")
        for raw in reader:
            index_raw = str(raw.get("index", "")).strip()
            if not index_raw:
                continue
            skipped = bool(int(float(raw.get("skipped") or 0)))
            correct = bool(int(float(raw.get("correct") or 0)))
            pairs.append(
                PairResult(
                    index=int(index_raw),
                    ground_truth=str(raw.get("ground_truth", "")).strip(),
                    filename=str(raw.get("filename", "")).strip(),
                    disease_pred=str(raw.get("disease_pred", "")).strip(),
                    gate_pred=str(raw.get("gate_pred", "")).strip(),
                    correct=correct,
                    skipped=skipped,
                    infer_ms=int(float(raw.get("infer_ms") or 0)),
                    gate_ms=int(float(raw.get("gate_ms") or 0)),
                )
            )
    return pairs


def report_from_pairs(paired: List[PairResult]) -> AnalysisReport:
    """Rebuild an AnalysisReport from PairResult rows (e.g. results.csv)."""
    report = AnalysisReport(paired=list(paired))
    per_class_correct: Dict[str, int] = defaultdict(int)
    per_class_total: Dict[str, int] = defaultdict(int)
    confusion: Dict[str, Counter] = defaultdict(Counter)
    infer_times: List[int] = []
    gate_times: List[int] = []

    for row in paired:
        report.gate_counts[row.gate_pred or "?"] += 1
        gate_times.append(row.gate_ms)
        if row.skipped:
            report.skipped += 1
            continue
        gt = row.ground_truth.lower()
        pred = row.disease_pred.lower()
        per_class_total[gt] += 1
        confusion[gt][pred] += 1
        infer_times.append(row.infer_ms)
        report.evaluated += 1
        if row.correct:
            per_class_correct[gt] += 1
            report.correct += 1

    report.overall_accuracy = (
        report.correct / report.evaluated if report.evaluated else 0.0
    )
    report.mean_infer_ms = (
        sum(infer_times) / len(infer_times) if infer_times else 0.0
    )
    report.mean_gate_ms = sum(gate_times) / len(gate_times) if gate_times else 0.0
    report.confusion = dict(confusion)
    report.per_class = {
        cls: {
            "correct": float(per_class_correct[cls]),
            "total": float(per_class_total[cls]),
            "accuracy": (
                per_class_correct[cls] / per_class_total[cls]
                if per_class_total[cls]
                else 0.0
            ),
        }
        for cls in sorted(per_class_total.keys())
    }
    return report


def load_saved_run_analysis(run_dir: Path) -> Tuple[AnalysisReport, Path, str]:
    """
    Load analysis for a run folder.

    Preference:
      1. Recompute from metadata.json + archived SD .csv (any name except results.csv)
      2. Else load from results.csv

    Returns (report, source_csv_path, source_kind) where source_kind is
    ``"sd_csv"`` or ``"results_csv"``.
    """
    from .metadata import load_run

    run_dir = Path(run_dir)
    inference_files = list_csv_files(run_dir, exclude_results=True)
    if len(inference_files) >= 2:
        names = ", ".join(p.name for p in inference_files)
        raise ValueError(
            f"Found {len(inference_files)} inference .csv files in run folder "
            f"(expected at most one): {names}"
        )

    if len(inference_files) == 1:
        meta = load_run(run_dir)
        csv_path = inference_files[0]
        report = analyze(meta, load_inference_csv(csv_path))
        return report, csv_path, "sd_csv"

    results = results_csv_path(run_dir)
    if results is not None and results.is_file():
        paired = load_results_csv(results)
        if not paired:
            raise ValueError(f"{results.name} is empty: {results}")
        return report_from_pairs(paired), results, "results_csv"

    raise FileNotFoundError(
        f"No analysis data in {run_dir.name}. "
        "Expected an SD inference .csv and/or analysis_results.csv."
    )


def load_inference_csv(path: Path) -> List[InferenceRow]:
    path = Path(path)
    rows: List[InferenceRow] = []
    with path.open(newline="", encoding="utf-8-sig") as fh:
        # Skip blank / comment lines before the header.
        filtered = (
            line for line in fh if line.strip() and not line.lstrip().startswith("#")
        )
        reader = csv.DictReader(filtered)
        if not reader.fieldnames:
            raise ValueError(f"Empty CSV: {path}")
        for raw in reader:
            id_raw = str(raw.get("id", "")).strip()
            if not id_raw:
                continue
            try:
                rows.append(
                    InferenceRow(
                        id=int(id_raw),
                        gate_pred=str(raw.get("gate_pred", "")).strip(),
                        pct_leaf=int(float(raw.get("pct_leaf") or 0)),
                        pct_others=int(float(raw.get("pct_others") or 0)),
                        pct_pest=int(float(raw.get("pct_pest") or 0)),
                        disease_pred=str(raw.get("disease_pred", "")).strip(),
                        gate_ms=int(float(raw.get("gate_ms") or 0)),
                        infer_ms=int(float(raw.get("infer_ms") or 0)),
                        bmp=str(raw.get("bmp", "")).strip(),
                    )
                )
            except (TypeError, ValueError) as exc:
                raise ValueError(f"Bad CSV row in {path}: {raw}") from exc
    rows.sort(key=lambda r: r.id)
    return rows


def analyze(meta: RunMetadata, predictions: List[InferenceRow]) -> AnalysisReport:
    """
    Pair test-set metadata with SD predictions by sequential id.

    Capture order on the bench is 1..N; the STM32 logger writes id=1,2,...
    so index == id is the default alignment.
    """
    by_id = {row.id: row for row in predictions}
    report = AnalysisReport()

    per_class_correct: Dict[str, int] = defaultdict(int)
    per_class_total: Dict[str, int] = defaultdict(int)
    confusion: Dict[str, Counter] = defaultdict(Counter)
    infer_times: List[int] = []
    gate_times: List[int] = []

    used_ids = set()
    for img in meta.images:
        pred = by_id.get(img.index)
        if pred is None:
            report.unmatched_meta += 1
            continue
        used_ids.add(pred.id)

        disease = pred.disease_pred.strip()
        skipped = disease.upper() in {"", "SKIP", "NONE", "N/A", "-"}
        gt = img.class_name.lower()
        pred_label = disease.lower()
        correct = (not skipped) and pred_label == gt

        pair = PairResult(
            index=img.index,
            ground_truth=img.class_name,
            filename=img.filename,
            disease_pred=disease,
            gate_pred=pred.gate_pred,
            correct=correct,
            skipped=skipped,
            infer_ms=pred.infer_ms,
            gate_ms=pred.gate_ms,
        )
        report.paired.append(pair)
        report.gate_counts[pred.gate_pred or "?"] += 1
        gate_times.append(pred.gate_ms)
        if not skipped:
            infer_times.append(pred.infer_ms)
            per_class_total[gt] += 1
            confusion[gt][pred_label] += 1
            if correct:
                per_class_correct[gt] += 1
                report.correct += 1
            report.evaluated += 1
        else:
            report.skipped += 1

    report.unmatched_preds = sum(1 for row in predictions if row.id not in used_ids)
    report.overall_accuracy = (
        report.correct / report.evaluated if report.evaluated else 0.0
    )
    report.mean_infer_ms = (
        sum(infer_times) / len(infer_times) if infer_times else 0.0
    )
    report.mean_gate_ms = sum(gate_times) / len(gate_times) if gate_times else 0.0
    report.confusion = dict(confusion)
    report.per_class = {
        cls: {
            "correct": float(per_class_correct[cls]),
            "total": float(per_class_total[cls]),
            "accuracy": (
                per_class_correct[cls] / per_class_total[cls]
                if per_class_total[cls]
                else 0.0
            ),
        }
        for cls in sorted(per_class_total.keys())
    }
    return report


def write_report_csv(report: AnalysisReport, path: Path) -> Path:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", newline="", encoding="utf-8") as fh:
        writer = csv.writer(fh)
        writer.writerow(
            [
                "index",
                "ground_truth",
                "filename",
                "disease_pred",
                "gate_pred",
                "correct",
                "skipped",
                "gate_ms",
                "infer_ms",
            ]
        )
        for row in report.paired:
            writer.writerow(
                [
                    row.index,
                    row.ground_truth,
                    row.filename,
                    row.disease_pred,
                    row.gate_pred,
                    int(row.correct),
                    int(row.skipped),
                    row.gate_ms,
                    row.infer_ms,
                ]
            )
    return path


def archive_log_to_run(source_csv: Path, run_dir: Path) -> Path:
    """
    Copy the original SD .csv into the run folder, keeping its filename.

    The source file on the SD card is left in place. If a file with the same
    name already exists in the run folder and the source is different, the
    existing file is renamed with a ``_previous`` suffix first.
    """
    source_csv = Path(source_csv).resolve()
    run_dir = Path(run_dir).resolve()
    run_dir.mkdir(parents=True, exist_ok=True)
    dest = run_dir / source_csv.name

    if source_csv == dest:
        return dest

    if dest.exists():
        backup = run_dir / f"{dest.stem}_previous{dest.suffix}"
        if backup.exists():
            backup.unlink()
        dest.rename(backup)

    shutil.copy2(str(source_csv), str(dest))
    return dest


def confusion_matrix_labels(report: AnalysisReport) -> Tuple[List[str], List[List[int]]]:
    labels = sorted(
        {
            *report.confusion.keys(),
            *(pred for counter in report.confusion.values() for pred in counter),
        }
    )
    matrix = [
        [int(report.confusion.get(gt, Counter()).get(pred, 0)) for pred in labels]
        for gt in labels
    ]
    return labels, matrix
